// buildPlan：本场景仅 2/9 只注入了指标（缺指标比例≥2/3）→ 按新规则整体降级、本轮不出推荐
const T4b = P.totals(r4);
const plan4 = P.buildPlan(50000, r4, T4b);
console.log('  带指标(仅2/9)本金 50000 → degraded=' + !!plan4.degraded + '，计划 ' + plan4.items.length + ' 项');
ok(plan4.degraded === true && plan4.items.length === 0, '缺指标比例≥2/3 → 整体降级本轮不买（#6 判定）');
ok(!plan4.items.some(x => x.r.code === '601000'), '唐山港未达标（若评估）不在买入清单');

tool_input.old_string:
// buildPlan 应优先推荐 marginBuy 的标的，且不推荐未达标的
const T4b = P.totals(r4);
const plan4 = P.buildPlan(50000, r4, T4b);
console.log('  带指标本金 50000 → 计划 ' + plan4.items.length + ' 项：' +
  plan4.items.map(x => x.r.name).join('、'));
ok(plan4.items.length > 0, '带指标时仍能给出买入清单');
ok(plan4.items.every(x => x.r.marginBuy || !x.r.margin), '推荐项要么 marginBuy 触发、要么无指标退化（不推荐未达标的）');
ok(!plan4.items.some(x => x.r.code === '601000'), '唐山港未达标，不在买入清单');
